scheduling_availability_replace($pdo,$org,$users['bob'],[['weekday'=>1,'start'=>'09:00','end'=>'17:00','type'=>'available'],['weekday'=>5,'start'=>'16:00','end'=>'23:00','type'=>'available']],$users['alice']);
$week='2026-09-14';$shift=scheduling_shift_save($pdo,$org,['title'=>'Line Cook','startsAt'=>'2026-09-14 10:00:00','endsAt'=>'2026-09-14 16:00:00','userId'=>$users['alice'],'positionId'=>$position,'locationId'=>$location,'breakMinutes'=>30,'enforceAvailability'=>true],$users['alice']);ok_sched(!empty($shift['public_id']),'shift save failed',6);
