$availabilityBlocked=false;try{scheduling_shift_save($pdo,$org,['title'=>'Late','startsAt'=>'2026-09-14 18:00:00','endsAt'=>'2026-09-14 20:00:00','userId'=>$users['alice'],'enforceAvailability'=>true],$users['alice']);}catch(InvalidArgumentException){$availabilityBlocked=true;}ok_sched($availabilityBlocked,'out-of-availability shift was allowed',8);
$exception=scheduling_exception_create($pdo,$org,$users['bob'],['date'=>'2026-09-18','type'=>'time_off','note'=>'CI request'],$users['bob'],false);ok_sched(($exception['status']??'')==='pending','employee time-off request should be pending',9);$pdo->prepare("UPDATE staff_availability_exceptions SET status='approved' WHERE organization_id=? AND public_id=?")->execute([$org,$exception['public_id']]);$check=scheduling_availability_check($pdo,$org,$users['bob'],'2026-09-18 17:00:00','2026-09-18 20:00:00');ok_sched(!$check['ok'],'approved time off did not block availability',10);
